<body>
<div id="wrap"><canvas id="game"></canvas></div>
<script>
(() => {
'use strict';

// ---------- setup ----------
const GAME_W = 960, GAME_H = 540;
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
let scale = 1, ox = 0, oy = 0;

function resize() {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const vw = window.innerWidth, vh = window.innerHeight;
  scale = Math.min(vw / GAME_W, vh / GAME_H);
  canvas.width = Math.round(GAME_W * scale * dpr);
  canvas.height = Math.round(GAME_H * scale * dpr);
  canvas.style.width = (GAME_W * scale) + 'px';
  canvas.style.height = (GAME_H * scale) + 'px';
  ctx.setTransform(scale * dpr, 0, 0, scale * dpr, 0, 0);
}
window.addEventListener('resize', resize);
resize();

function toGame(e) {
  const r = canvas.getBoundingClientRect();
  const cx = (e.clientX - r.left) / r.width * GAME_W;
  const cy = (e.clientY - r.top) / r.height * GAME_H;
  return { x: cx, y: cy };
}

// ---------- audio ----------
let audioCtx = null;
function ac() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  if (audioCtx.state === 'suspended') audioCtx.resume();
  return audioCtx;
}
function tone(freq, dur, type, vol, slideTo, delay = 0) {
  const a = ac(), t = a.currentTime + delay;
  const o = a.createOscillator(), g = a.createGain();
  o.type = type; o.frequency.setValueAtTime(freq, t);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g).connect(a.destination);
  o.start(t); o.stop(t + dur + 0.05);
}
function noise(dur, vol, filterFreq, delay = 0) {
  const a = ac(), t = a.currentTime + delay;
  const len = Math.max(1, Math.floor(a.sampleRate * dur));
  const buf = a.createBuffer(1, len, a.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
  const src = a.createBufferSource(); src.buffer = buf;
  const f = a.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = filterFreq;
  const g = a.createGain(); g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  src.connect(f).connect(g).connect(a.destination);
  src.start(t);
}
const sfx = {
  drawStart() { tone(180, 0.12, 'triangle', 0.05, 260); },
  release(power) {
    noise(0.09, 0.35, 1800); tone(320 + power * 240, 0.14, 'square', 0.16, 90);
  },
  pop(big) {
    noise(0.18, 0.5, 2600); tone(big ? 420 : 520, 0.16, 'sine', 0.28, 120);
    tone(900, 0.05, 'square', 0.12, 500, 0.02);
  },
  miss() { tone(200, 0.35, 'sawtooth', 0.16, 70); },
  start() { tone(440, 0.1, 'square', 0.14); tone(660, 0.12, 'square', 0.14, null, 0.1); tone(880, 0.2, 'square', 0.14, null, 0.2); },
  over() { tone(520, 0.25, 'sawtooth', 0.18, 380); tone(392, 0.3, 'sawtooth', 0.18, 250, 0.22); tone(261, 0.7, 'sawtooth', 0.18, 130, 0.48); },
  score() { tone(920, 0.07, 'sine', 0.1, 1300); },
};

// ---------- game state ----------
